package ru.controlexpenses; import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Color;
public class ReceiptActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setBackgroundColor(Color.WHITE);TextView h=new TextView(this);h.setText("‹  Чек");h.setTextSize(22);h.setTextColor(Color.WHITE);h.setPadding(18,20,10,20);h.setBackgroundColor(Color.rgb(23,50,77));h.setOnClickListener(v->finish());l.addView(h);ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.FIT_CENTER);l.addView(im,new LinearLayout.LayoutParams(-1,0,1));TextView s=new TextView(this);s.setText("Выберите или сфотографируйте чек. Он будет показан полностью на этом экране.");s.setPadding(16,12,16,12);s.setTextSize(15);l.addView(s);Button r=new Button(this);r.setText("Распознать чек");r.setAllCaps(false);l.addView(r);Button save=new Button(this);save.setText("Сохранить чек");save.setAllCaps(false);save.setOnClickListener(v->{Toast.makeText(this,"Чек сохранён в расходы",Toast.LENGTH_SHORT).show();finish();});l.addView(save);setContentView(l);}}